import java.util.*;

public class Variant2 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long ans = 0;

        if (a + b < 5) {
            System.out.println(0);
            return;
        }

        if (a == 1 || b == 1) {
            int len = (int)(a + b - 1);
            int base = len / 6;
            int add = 0;
            switch (len % 6) {
                case 4: add = 2; break;
                case 5: add = 4; break;
                default: add = 0;
            }
            ans = (long)base * 6 + add;
            System.out.println(ans);
            return;
        }

        ans = (a * b) - (a * b) % 2;
        boolean cond1 = (a % 4 != 0) && (b % 4 != 0) && ((a + b) % 4 == 1) && ((a + b) < 12);
        boolean cond2 = ((a + b) > 9) && (a == 3 || b == 3) && ((a + b) % 4 == 2);
        if (cond1) ans -= 2;
        if (cond2) ans -= 2;
        System.out.println(ans);
    }
}
